using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about an action to be done when the current user clicks an external link. Don't use this method for links from secret chats if link preview is disabled in secret chats
    /// </summary>
    public Task<TdLib.TdApi.Objects.LoginUrlInfo> GetExternalLinkInfoAsync(string link = default)
    {

           using var activity =  StartCallActivity("GetExternalLinkInfoAsync", typeof(GetExternalLinkInfo).FullName ?? "GetExternalLinkInfoAsync");

           try
           {
             return client.GetExternalLinkInfoAsync(link);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
